const ROW_HEIGHT = 64;

export function MessageList({
  messages,
  selectedId,
  onSelect,
}: {
  messages: Message[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}) {
  return (
    <FlatList
      data={messages}
      getItemLayout={(_, index) => ({
        length: ROW_HEIGHT,
        offset: ROW_HEIGHT * index,
        index,
      })}
      renderItem={({ item }) => (
        <Row
          message={item}
          selected={item.id === selectedId}
          onPress={() => onSelect(item.id)}
        />
      )}
      keyExtractor={(item) => item.id}
    />
  );
}
